source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    patterns = []
    reference_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            run = row[start:c]
            if len(run) >= 2:
                patterns.append(run)
                reference_cells.update((r, x) for x in range(start, c))
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0 or (r, c) in reference_cells:
                continue
            pattern = next((run for run in patterns if color in run), None)
            if pattern is None:
                continue
            left = c - pattern.index(color)
            for j, value in enumerate(pattern):
                target = left + j
                if 0 <= target < w:
                    out[r][target] = value
    return out
'''
